            "        \"seasons\": [\n" +
            "            {\n" +
            "                \"itemType\": \"season\",\n" +
            "                \"title\": \"Season 1\",\n" +
            "                \"firstAirYear\": 2014,\n" +
            "                \"lastAirYear\": 2015,\n" +
            "                \"episodes\": [\n" +
            "                    {\n" +
            "                        \"itemType\": \"episode\",\n" +
            "                        \"title\": \"Pilot\",\n" +
            "                        \"overview\": \"Gordon and his world-weary partner Harvey Bullock investigate the killings of billionaire philanthropist Thomas Wayne and his wife Martha. The only witness to their shootings being the couple's young son Bruce.\",\n" +
            "                        \"airYear\": 2014\n" +
            "                    },\n" +
            "                    {\n" +
            "                        \"itemType\": \"episode\",\n" +
            "                        \"title\": \"Selina Kyle\",\n" +
            "                        \"overview\": \"Gordon hits the streets on the trail of two child snatchers, who are targeting the city's homeless youths. One of the youngsters displays a cat-like ability to fall on her feet and suggests that she has some information.\",\n" +
            "                        \"airYear\": 2014\n" +
            "                    },\n" +
            "                    {\n" +
            "                        \"itemType\": \"episode\",\n" +
            "                        \"title\": \"The Balloonman\",\n" +
            "                        \"overview\": \"Gordon and Bullock are on the trail of a vigilante who takes the law into his own hands by attaching people of dubious morals to huge weather balloons then letting them float off into oblivion.\",\n" +
            "                        \"airYear\": 2014\n" +
            "                    },\n" +
            "                    {\n" +
            "                        \"itemType\": \"episode\",\n" +
            "                        \"title\": \"Arkham\",\n" +
            "                        \"overview\": \"As the mayor is about to announce the council's decision over who has the right to develop a valuable swathe of land occupied by the decaying Arkham Asylum, James and Bullock go on the search of a hitman who has been hired to influence the vote.\",\n" +
            "                        \"airYear\": 2014\n" +
            "                    },\n" +
            "                    {\n" +
            "                        \"itemType\": \"episode\",\n" +
            "                        \"title\": \"Viper\",\n" +
            "                        \"overview\": \"Gordon and Bullock try to clean up the streets after a demonic chemist infects the city with drug that kills after the infected have caused chaos. Meanwhile, young Bruce Wayne starts to piece together the whole picture behind Wayne Enterprises.\",\n" +
            "                        \"airYear\": 2014\n" +
            "                    },\n" +
            "                    {\n" +
            "                        \"itemType\": \"episode\",\n" +
            "                        \"title\": \"Spirit of the Goat\",\n" +
            "                        \"overview\": \"Gotham is plagued by an apparently resurrected serial killer whose target is the offspring of the city's wealthiest citizens. Meanwhile, the net closes around Gordon for Oswald Cobblepot's murder. However, the net has one big hole in it.\",\n" +
            "                        \"airYear\": 2014\n" +
            "                    },\n" +
            "                    {\n" +
            "                        \"itemType\": \"episode\",\n" +
            "                        \"title\": \"Penguin's Umbrella\",\n" +
            "                        \"overview\": \"As violence between Maroni and Falcone escalates, Penguin reveals a new element of his manipulative strategy, forcing Gordon to deal with the consequences of his earlier decision.\",\n" +
            "                        \"airYear\": 2014\n" +
            "                    },\n" +
            "                    {\n" +
            "                        \"itemType\": \"episode\",\n" +
            "                        \"title\": \"The Mask\",\n" +
            "                        \"overview\": \"When a Gothamite is found beaten to death, Gordon and Bullock are intrigued by the motive and take on the case. Meanwhile, Bruce returns to school and has trouble making friends.\",\n" +
            "                        \"airYear\": 2014\n" +
            "                    },\n" +
            "                    {\n" +
            "                        \"itemType\": \"episode\",\n" +
            "                        \"title\": \"Harvey Dent\",\n" +
            "                        \"overview\": \"Trying to close the Wayne murder case, a young Harvey Dent encourages Gordon to team up with Mayor James. Meanwhile, Penguin makes contact with Mooney’s secret weapon, Liza.\",\n" +
            "                        \"airYear\": 2014\n" +
            "                    },\n" +
            "                    {\n" +
            "                        \"itemType\": \"episode\",\n" +
            "                        \"title\": \"Lovecraft\",\n" +
            "                        \"overview\": \"Selina leads a new friend on a perilous journey through Gotham to evade the assassins on her trail. And Gordon is reassigned to duty at Arkham Asylum following a misstep.\",\n" +
            "                        \"airYear\": 2014\n" +
            "                    },\n" +
            "                    {\n" +
            "                        \"itemType\": \"episode\",\n" +
            "                        \"title\": \"Rogue's Gallery\",\n" +
            "                        \"overview\": \"Det. Gordon’s assignment at Arkham Asylum gets off to a rocky start when the murder of a guard ignites an investigation, leading him to meet Dr. Leslie Tompkins (MORENA BACCARIN).\",\n" +
            "                        \"airYear\": 2015\n" +
            "                    },\n" +
            "                    {\n" +
            "                        \"itemType\": \"episode\",\n" +
            "                        \"title\": \"What the Little Bird Told Him\",\n" +
            "                        \"overview\": \"Gordon seeks to capture Jack Gruber, a deranged electrical genius who escapes Arkham. Meanwhile, Falcone struggles to hold on to his empire after Fish Mooney makes her next move.\",\n" +
            "                        \"airYear\": 2015\n" +
            "                    },\n" +
            "                    {\n" +
            "                        \"itemType\": \"episode\",\n" +
            "                        \"title\": \"Welcome Back, Jim Gordon\",\n" +
